import { createHash, createHmac, randomUUID } from 'node:crypto';
import fs from 'node:fs/promises';
import WebSocket from '/usr/local/lib/node_modules/@deepseek-ai/dsh/node_modules/ws/index.js';

const b64u = (b) => Buffer.from(b).toString('base64').replaceAll('+', '-').replaceAll('/', '_').replace(/=+$/, '');
const y = await fs.readFile(process.env.HOME + '/.dsh/.credentials.yaml', 'utf8');
const m = y.match(/client-connection\/browser-session:[\s\S]*?secret:\s*([A-Za-z0-9_-]+)/);
const sec = Buffer.from(m[1].replaceAll('-', '+').replaceAll('_', '/') + '='.repeat((4 - (m[1].length % 4)) % 4), 'base64');
const a = '127.0.0.1:3080';
const cname = 'dsh-auth-' + b64u(createHash('sha256').update(a).digest());
const t = Date.now();
const cbody = b64u(Buffer.from(JSON.stringify({ version: 1, authority: a, issuedAt: t, expiresAt: t + 12 * 3600 * 1000 }), 'utf8'));
const cookie = `${cname}=v1.${cbody}.${b64u(createHmac('sha256', sec).update(cbody).digest())}`;

const SESSION = 'session-9998fc67-4804-424f-ba80-3d05678aba7f';
const address = { kind: 'session', sessionId: SESSION };

const ws = new WebSocket('ws://127.0.0.1:3080/api/remote.mux', { headers: { cookie } });
const streamId = randomUUID();

ws.on('open', () => {
  ws.send(JSON.stringify({
    type: 'open',
    streamId,
    endpoint: 'session/follow',
    payload: { args: { request: { address, maxMessages: 60 } } },
  }));
});

